export const FIXTURE_NAMES = Object.freeze(Object.keys(PROJECTED_FIXTURES));

/** Return a fresh mutable snapshot for a fixture harness's selected role. */
export function getProjectedFixture(name, role = 'tv') {
  if (!Object.hasOwn(PROJECTED_FIXTURES, name) || !['tv', 'jon', 'lydia'].includes(role)) {
    throw new RangeError('Choose a known fixture and viewer.');
  }
  return JSON.parse(JSON.stringify(PROJECTED_FIXTURES[name][role]));
}
